   "_locales/de/neopixel-jsdoc-strings.json": {
    "text": "{\n  \"neopixel.create\": \"Erzeuge einen neuen Treiber für die gegebene Anzahl NeoPixels, die am angegebenen Port angeschlossen sind. Der Modus bestimmt die genaue Bauart der NeoPixel.\",\n  \"neopixel.Strip.showColor\": \"Setze alle Pixel auf die angegebene Farbe und rufe ``anzeigen`` auf.\",\n  \"neopixel.Strip.setBrigthness\": \"Setze die Helligkeit der NeoPixel (0-255). Die Änderung betrifft nur zukünftige Operationen.\",\n  \"neopixel.HSL.rotateHue\": \"Rotiert den Farbwert einer HSL-Farbe\",\n  \"neopixel.HSL.toRGB\": \"Konvertiert eine HSL-Farbe in eine RGB-Farbe.\",\n  \"neopixel.Strip.clear\": \"Schalte alle NeoPixel aus. Damit die Änderung sichtbar wird, muss anschließend ``anzeigen`` aufgerufen werden.\",\n  \"neopixel.Strip.easeBrightness\": \"Aktuelle Farben der NeoPixel je nach Pixelnr. abdunkeln.\",\n  \"neopixel.Strip.length\": \"Die Anzahl der NeoPixel, die der Treiber verwaltet.\",\n  \"neopixel.Strip.range\": \"Erstellt einen neuen Treiber für ein Intervall der vom angegebenen Treiber verwalteten NeoPixel.\",\n  \"neopixel.Strip.rotate\": \"Rotiert die Farben der NeoPixel. Damit die Änderung sichtbar wird, muss anschließend ``anzeigen`` aufgerufen werden.\",\n  \"neopixel.Strip.setPixelColor\": \"Setzt den NeoPixel mit der angegebenen Nr. auf die angegebene Farbe. Damit die Änderung sichtbar wird, muss anschließend ``anzeigen`` aufgerufen werden.\",\n  \"neopixel.Strip.setPixelWhiteLED\": \"Setzt die Helligkeit der weißen LED des NeoPixels mit der angegebenen Nr. Dies funktioniert nur für RGB+W Neopixel. Damit die Änderung sichtbar wird, muss anschließend ``anzeigen`` aufgerufen werden.\",\n  \"neopixel.Strip.shift\": \"Verschiebt die Farben der NeoPixel. Damit die Änderung sichtbar wird, muss anschließend ``anzeigen`` aufgerufen werden.\",\n  \"neopixel.Strip.showBarGraph\": \"Zeigt den angegebenen Wert in Bezug auf das gegebene Maximum als Balkendiagramm auf allen Neopixeln an.\",\n  \"neopixel.Strip.showRainbow\": \"Zeigt ein Regenbogenmuster auf allen NeoPixeln an.\",\n  \"neopixel.Strip.show\": \"Sendet alle Änderungen an die NeoPixel.\",\n  \"neopixel.hsl\": \"Erstellt eine HSL-Farbe\",\n  \"neopixel.rgb\": \"Erstellt eine RGB-Farbe\",\n  \"neopixel.colors\": \"bekannte RGB-Farben\"\n}\n",
    "blob": "d92098967392d9d74f73aad8107d9ce490b29209"
   },
