   "_locales/fr/neopixel-jsdoc-strings.json": {
    "text": "{\n  \"NeoPixelColors\": \"Les couleurs pour une bande NeoPixel.\",\n  \"NeoPixelMode\": \"Les différents modes pour les bandes NeoPixel RGB ou RGB+W.\",\n  \"neopixel\": \"La fonction pour piloter les bandes NeoPixel.\",\n  \"neopixel.Strip\": \"La bande NeoPixel.\",\n  \"neopixel.Strip.clear\": \"Éteint toutes les DELs.\\nIl faut ``afficher`` le changement (second bloc) pour le rendre visible.\",\n  \"neopixel.Strip.easeBrightness\": \"Atténue la luminosité de la couleur avec une fonction quadratique.\",\n  \"neopixel.Strip.length\": \"Calcule le nombre de DELs sur la bande.\",\n  \"neopixel.Strip.power\": \"Estime la consommation électrique (mA) de la configuration.\",\n  \"neopixel.Strip.range\": \"Crée une séquence de DELs.\",\n  \"neopixel.Strip.range|param|length\": \"Le nombre de DELs dans la séquence. 4, par exemple.\",\n  \"neopixel.Strip.range|param|start\": \"Décale les DELs sur la bande, depuis le début de la bande.\",\n  \"neopixel.Strip.rotate\": \"Pivote les DELs vers l'avant. \\nIl faut ``afficher`` le changement (second bloc) pour le rendre visible.\",\n  \"neopixel.Strip.rotate|param|offset\": \"Le nombre de DELs dans le pivot avant. 1, par exemple.\",\n  \"neopixel.Strip.setBrightness\": \"Détermine la luminosité de la bande. Le réglage est appliqué les instructions suivantes.\",\n  \"neopixel.Strip.setBrightness|param|brightness\": \"La mesure de la luminosité des DELs, entre 0 et 255. 255, par exemple.\",\n  \"neopixel.Strip.setMatrixColor\": \"Règle les DELs sur une couleur données (selon une séquence de 0 à 255 pour Rouge, Green (vert), Bleu) dans une bande en forme de matrice. \\nIl faut ``afficher`` le changement (second bloc) pour le rendre visible.\",\n  \"neopixel.Strip.setMatrixColor|param|rgb\": \"La couleur RGB (rouge-vert-bleu) des DELs.\",\n  \"neopixel.Strip.setMatrixColor|param|x\": \"La position horizontale (ligne).\",\n  \"neopixel.Strip.setMatrixColor|param|y\": \"La position verticale (colonne).\",\n  \"neopixel.Strip.setMatrixWidth\": \"Détermine le nombre de DELs dans la bande en forme de matrice.\",\n  \"neopixel.Strip.setMatrixWidth|param|width\": \"Le nombre de DELs sur une ligne.\",\n  \"neopixel.Strip.setPin\": \"Détermine la broche où le NeoPixel est branché; broche P0, par défaut.\",\n  \"neopixel.Strip.setPixelColor\": \"Règle les DELs sur une couleur données (selon une séquence de 0 à 255 pour rouge-vert-bleu) \\nIl faut ``afficher`` le changement (second bloc) pour le rendre visible.\",\n  \"neopixel.Strip.setPixelColor|param|pixeloffset\": \"La position du NeoPixel sur la bande.\",\n  \"neopixel.Strip.setPixelColor|param|rgb\": \"La couleur RGB (rouge-vert-bleu) de la DEL.\",\n  \"neopixel.Strip.setPixelWhiteLED\": \"Pour le NeoPixels avec des DELs RGB+W (rouge-vert-bleu-blanc), détermine la luminosité des DEL blanches. Ceci ne fonctionne que pour les NeoPixels RGB+W.\",\n    \"neopixel.Strip.setPixelWhiteLED|param|pixeloffset\": \"La position de la DEL sur la bande.\",\n  \"neopixel.Strip.setPixelWhiteLED|param|white\": \"La luminosité des DEL blanches.\",\n  \"neopixel.Strip.shift\": \"Décale les DELs vers l'avant et supprime les quelques DELs perdues de la fin.\\nIl faut ``afficher`` le changement (second bloc) pour le rendre visible.\",\n  \"neopixel.Strip.shift|param|offset\": \"Le nombre de DELs décalé vers l'avant. 1, par exemple.\",\n  \"neopixel.Strip.show\": \"Affiche tous les changements sur la bande.\",\n  \"neopixel.Strip.showBarGraph\": \"Trace un graphe de barres verticales basé sur la `valeur` en cours et la valeur `maximale`.\\nSi la valeur `maximale` est 0, le graphe s'ajuste automatiquement.\",\n  \"neopixel.Strip.showBarGraph|param|high\": \"La valeur maximale. 255, par exemple.\",\n  \"neopixel.Strip.showBarGraph|param|value\": \"La valeur en cours à tracer.\",\n  \"neopixel.Strip.showColor\": \"Règle toutes les DELs sur une couleur donnée (séquence de 0 à 255 pour rouge-vert-bleu).\",\n  \"neopixel.Strip.showColor|param|rgb\": \"Les couleurs RGB (rouge-vert-bleu) des DELs.\",\n  \"neopixel.Strip.showRainbow\": \"Affiche un patron arc-en-ciel sur toutes les DELs.\",\n  \"neopixel.Strip.showRainbow|param|endHue\": \"La valeur de la teinte en fin d'arc-en-ciel. 360, par exemple.\",\n  \"neopixel.Strip.showRainbow|param|startHue\": \"La valeur de la teinte en début d'arc-en-ciel. 1, par exemple.\",\n  \"neopixel.colors\": \"Collige les valeur RGB (rouge-vert-bleu) d'une couleur donnée.\",\n  \"neopixel.create\": \"Crée un nouveau pilote NeoPixel pour les DELs `numleds`.\",\n  \"neopixel.create|param|numleds\": \"Le nombre de DELs dans la bande. 24,30,60,64, par exemple\",\n  \"neopixel.create|param|pin\": \"La broche où le NeoPixel est branché.\",\n  \"neopixel.hsl\": \"Convertit une couleur teinte-saturation-luminosité en couleur RGB (rouge-vert-bleu).\",\n  \"neopixel.hsl|param|h\": \"La teinte de 0 à 360\",\n  \"neopixel.hsl|param|l\": \"La luminosité de 0 à 99\",\n  \"neopixel.hsl|param|s\": \"La saturation de 0 à 99\",\n  \"neopixel.rgb\": \"Convertit les canaux RGB (rouge-vert-bleu) en couleur RGB.\",\n  \"neopixel.rgb|param|blue\": \"La valeur du canal B, bleu, entre  0 et 255. 255, par exemple.\",\n  \"neopixel.rgb|param|green\": \"La valeur du canal G, vert, entre  0 et 255. 255, par exemple.\",\n  \"neopixel.rgb|param|red\": \"La valeur du canal R, rouge, entre  0 et 255. 255, par exemple.\"\n}\n",
    "blob": "1150dd14e1244e327d9786a1fe812b335fb16abc"
   },
