    "text": "{\n    \"name\": \"pxt-status-bar\",\n    \"version\": \"0.4.1\",\n    \"description\": \"\",\n    \"dependencies\": {\n        \"device\": \"*\"\n    },\n    \"files\": [\n        \"README.md\",\n        \"status-bar.ts\",\n        \"docs/value.md\",\n        \"docs/max.md\",\n        \"docs/attach-to-sprite.md\",\n        \"docs/sprite-attached-to.md\",\n        \"docs/set-color.md\",\n        \"docs/set-bar-border.md\",\n        \"docs/set-label.md\",\n        \"docs/set-status-bar-flag.md\",\n        \"docs/set-bar-size.md\",\n        \"docs/position-direction.md\",\n        \"docs/set-offset-padding.md\",\n        \"docs/create.md\",\n        \"docs/get-status-bar-attached-to.md\",\n        \"docs/on-zero.md\",\n        \"docs/on-status-reached.md\",\n        \"docs/on-display-updated.md\",\n        \"docs/all-of-kind.md\"\n    ],\n    \"testFiles\": [\n        \"test.ts\"\n    ],\n    \"public\": true,\n    \"targetVersions\": {\n        \"target\": \"1.3.44\",\n        \"targetId\": \"arcade\"\n    },\n    \"supportedTargets\": [\n        \"arcade\"\n    ],\n    \"preferredEditor\": \"tsprj\"\n}\n",
    "blob": "94f42d1fa6b1e24e74fe773abece7e73353db415"
